package net.civeira.phylax.feature.observe.observedissue.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class IgnoreUntilCountVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property ignore until count of observed issue ")
  void test_ignore_until_count_v_o_builder() {
    Assertions.assertFalse(IgnoreUntilCountVO.nullValue().getIgnoreUntilCount().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(IgnoreUntilCountVO.tryFrom(null).getIgnoreUntilCount().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(1, IgnoreUntilCountVO.from(1).getIgnoreUntilCount().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> IgnoreUntilCountVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", IgnoreUntilCountVO.from(1).toString());
  }
}
